package com.github.tartaricacid.touhoulittlemaid.molang.parser;

import com.github.tartaricacid.touhoulittlemaid.molang.lexer.Cursor;
import com.github.tartaricacid.touhoulittlemaid.molang.lexer.MolangLexer;
import com.github.tartaricacid.touhoulittlemaid.molang.parser.MolangParserImpl;
import com.github.tartaricacid.touhoulittlemaid.molang.parser.ast.Expression;
import com.github.tartaricacid.touhoulittlemaid.molang.runtime.binding.ObjectBinding;
import java.io.Closeable;
import java.io.IOException;
import java.io.Reader;
import java.util.ArrayList;
import java.util.List;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

public interface MolangParser
extends Closeable {
    @NotNull
    public MolangLexer lexer();

    @NotNull
    default public Cursor cursor() {
        return this.lexer().cursor();
    }

    @Nullable
    public Expression current();

    @Nullable
    public Expression next() throws IOException;

    @NotNull
    default public List<Expression> parseAll() throws IOException {
        Expression expr;
        ArrayList<Expression> tokens = new ArrayList<Expression>();
        while ((expr = this.next()) != null) {
            tokens.add(expr);
        }
        return tokens;
    }

    @Override
    public void close() throws IOException;

    @NotNull
    public static MolangParser parser(@NotNull MolangLexer lexer, @NotNull ObjectBinding binding) throws IOException {
        return new MolangParserImpl(lexer, binding);
    }

    @NotNull
    public static MolangParser parser(@NotNull Reader reader, @NotNull ObjectBinding binding) throws IOException {
        return MolangParser.parser(MolangLexer.lexer(reader), binding);
    }

    @NotNull
    public static MolangParser parser(@NotNull String string, @NotNull ObjectBinding binding) throws IOException {
        return MolangParser.parser(MolangLexer.lexer(string), binding);
    }

    @NotNull
    public static List<Expression> parseAll(@NotNull Reader reader, @NotNull ObjectBinding binding) throws IOException {
        try (MolangParser parser = MolangParser.parser(reader, binding);){
            List<Expression> list = parser.parseAll();
            return list;
        }
    }

    @NotNull
    public static List<Expression> parseAll(@NotNull String string, @NotNull ObjectBinding binding) throws IOException {
        try (MolangParser parser = MolangParser.parser(string, binding);){
            List<Expression> list = parser.parseAll();
            return list;
        }
    }
}

